import rclpy
from rclpy.node import Node

class PersonNode(Node):
    def __init__(self,node_name:str,name_value:str,age_value:int) -> None:
        print("PersonNode __init__ 被调用了")
        super().__init__(node_name)
        self.name=name_value
        self.age=age_value

    def eat(self,food_name:str):
        """
        方法eat接受一个参数food_name，表示食物的名称，并输出一个字符串，包含人的名字、年龄和喜欢吃的食物。
        food_name是一个字符串类型的参数，表示食物的名称
        
        """
        # print(f"{self.name},{self.age}岁，爱吃{food_name}")
        self.get_logger().info(f"{self.name},{self.age}岁，爱吃{food_name}")

def main():
    rclpy.init()
    node=PersonNode('zhangsan', '张三', 25)
    node.eat('鱼香ROS')
    rclpy.spin(node)
    rclpy.shutdown()

  